client.responses.create(model=MODEL, instructions='Answer the question using the web search results provided. Be concise and factual. Cite key details from the results.', input=f'Question: {query}

Search results:
{context}')

client.chat.completions.create(model='claude-opus-4-6', messages=[{'role': 'system', 'content': 'You are a helpful assistant that answers questions based on the provided context.'}, {'role': 'user', 'content': f"
                        Answer the following question based on the provided context:
                        Context: {state['context']}
                        Question: {state['question']}
                    "}])

self.agent.step(f'
                    Function is: {function_name}
                    Function description: {func.get_function_description()}
                    Args: {args}
                    Kwargs: {kwargs}
                    ')

self.anthropic_client.messages.create(model=RESEARCH_MODEL, max_tokens=2048, messages=[{'role': 'user', 'content': f'Does this debate question require current/recent information to answer well?

Question: {question}

Respond with just "yes" or "no".'}])

client.chat.completions.create(model='gpt-4o', messages=[{'role': 'system', 'content': 'You are a helpful assistant that extracts structured information from meeting descriptions. Always respond with valid JSON only.'}, {'role': 'user', 'content': f'
                        Extract the following information from this meeting description and return as JSON:
                        - participants: array of email addresses found in the text
                        - context: brief summary of the meeting type and context
                        - objective: what the user wants to achieve in the meeting

                        Text: {message}

                        Return format:
                        {{
                            "participants": ["email1@domain.com", "email2@domain.com"],
                            "context": "brief meeting context",
                            "objective": "what user wants to achieve"
                        }}
                        '}], temperature=0.1, max_tokens=500)

self.anthropic.messages.create(model='claude-3-5-sonnet-20241022', max_tokens=4096, messages=[{'role': 'user', 'content': f'Help me with this Airbnb request: {query}

Please use the available Airbnb tools to search for properties, get listing details, or provide accommodation assistance. 
Make sure to provide helpful, accurate information about available properties and booking options.'}], tools=self.tools)

self.client.chat.completions.create(model='google/gemini-2.5-flash', messages=[{'role': 'user', 'content': f"QUESTION: {question}

FACT: {fact_text}

Is this fact RELEVANT to answering the question? Answer ONLY 'yes' or 'no'. Relevant means it contains information that helps answer the question, even partially."}], temperature=0.0, max_tokens=5)

client.chat.completions.create(model=model, messages=[{'role': 'system', 'content': 'You are a support agent. Write a concise reply that acknowledges the issue, summarizes the next step, and stays professional and empathetic.'}, {'role': 'user', 'content': f'Use this structured context to draft the reply:
{json.dumps(extracted, indent=2)}

Write 3 to 4 sentences. Do not mention the JSON fields.'}], temperature=0.2)

_client().messages.create(model=MODEL, max_tokens=500, messages=[{'role': 'user', 'content': f"Eres asistente de email profesional. Redacta respuesta concisa (máx 150 palabras).
